return {["scripts/actions/abilities/tranquility.lua"]={["Path"]="scripts/actions/abilities/tranquility.lua",["SHA256"]="46a1c1a89a6d56c5ec0b20fc99ea39d4ab2ae7b467dcf688bd3d0d02a1b9ce32",["Text"]="-----------------------------------\n-- Ability: Tranquility\n-- Your next white magic spell will generate less enmity.\n-- Obtained: Scholar Level 75 Tier 2 Merit Points\n-- Recast Time: Stratagem Charge\n-- Duration: 1 white magic spell or 60 seconds, whichever occurs first\n--\n-- Level   |Charges |Recharge Time per Charge\n-- -----   -------- ---------------\n-- 10      |1       |4:00 minutes\n-- 30      |2       |2:00 minutes\n-- 50      |3       |1:20 minutes\n-- 70      |4       |1:00 minute\n-- 90      |5       |48 seconds\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.TRANQUILITY) then\n        return xi.msg.basic.EFFECT_ALREADY_ACTIVE, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:addStatusEffect(xi.effect.TRANQUILITY, { power = player:getMerit(xi.merit.TRANQUILITY), duration = 60, origin = player })\n\n    return xi.effect.TRANQUILITY\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/trick_attack.lua"]={["Path"]="scripts/actions/abilities/trick_attack.lua",["SHA256"]="82a5fdd200a6d8890feee6c89017ee74f0d021fb11581be2650bff1a05ef274c",["Text"]="-----------------------------------\n-- Ability: Trick Attack\n-- Deals extra damage when striking from behind a party or alliance member.\n-- Obtained: Thief Level 30\n-- Recast Time: 1:00\n-- Duration: 1:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.thief.useTrickAttack(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/triple_shot.lua"]={["Path"]="scripts/actions/abilities/triple_shot.lua",["SHA256"]="9860e5496a2cfae3e9ccba0835e1225d2469d6f673bfa0c75708dd54183ec2ab",["Text"]="-----------------------------------\n-- Ability: Triple Shot\n-- Description: Occasionally uses three units of ammunition to deal extra damage.\n-- Obtained: COR Level 87\n-- Recast Time: 00:05:00\n-- Duration: 0:01:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:addStatusEffect(xi.effect.TRIPLE_SHOT, { power = 40, duration = 90, origin = player })\n\n    return xi.effect.TRIPLE_SHOT\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/troubadour.lua"]={["Path"]="scripts/actions/abilities/troubadour.lua",["SHA256"]="100864e1c4729f3a6bc847766d7e9077c011d6a5d5a10fe733702e236ae2756f",["Text"]="-----------------------------------\n-- Ability: Troubadour\n-- Game Description: Increases the casting time of songs by 1.5 and doubles the effect duration\n-- Obtained: Bard by Merit Points at Level 75\n-- Recast Time: 0:10:00\n-- Duration: 0:01:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.bard.useTroubadour(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/unbridled_learning.lua"]={["Path"]="scripts/actions/abilities/unbridled_learning.lua",["SHA256"]="13465be274cb0058562c78cc6582a016136b6caead1ce76de99061ec05e38366",["Text"]="-----------------------------------\n-- Ability: Unbridled Learning\n-- Description: Allows access to additional blue magic spells.\n-- Obtained: BLU Level 95\n-- Recast