\n    return xi.job_utils.ranger.checkVelocityShot(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.ranger.useVelocityShot(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/ventriloquy.lua"]={["Path"]="scripts/actions/abilities/ventriloquy.lua",["SHA256"]="689c12b07fd0bb7aa52f1068cd5cb2bcbe28859f562d74dd23203c3c7a129abf",["Text"]="-----------------------------------\n-- Ability: Ventriloquy\n-- Swaps the enmity of master and automaton for target.\n-- Obtained: Puppetmaster Level 75\n-- Recast Time: 1:00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.puppetmaster.onAbilityCheckVentriloquy(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.puppetmaster.onAbilityUseVentriloquy(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/violent_flourish.lua"]={["Path"]="scripts/actions/abilities/violent_flourish.lua",["SHA256"]="c2182c9ba726e696f43251b6711db72fa96ff5446e838c075c3afa21889ad943",["Text"]="-----------------------------------\n-- Ability: Violent Flourish\n-- Stuns target with a low rate of success. Requires one Finishing Move.\n-- Obtained: Dancer Level 45\n-- Finishing Moves Used: 1\n-- Recast Time: 0:20\n-- Duration: ??\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.dancer.checkFlourishAbility(player, target, ability, true, 1)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.dancer.useViolentFlourishAbility(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/vivacious_pulse.lua"]={["Path"]="scripts/actions/abilities/vivacious_pulse.lua",["SHA256"]="5af1c480cd6ed9d7fa5aeaa79d5d8bd107798d4f210cab95d9fa7794aff1c3b7",["Text"]="-----------------------------------\n-- Ability: Vivacious Pulse\n-- Restores the caster's HP.\n-- Obtained: Rune Fencer Level 65\n-- Recast Time: 1:00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.rune_fencer.useVivaciousPulse(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/warcry.lua"]={["Path"]="scripts/actions/abilities/warcry.lua",["SHA256"]="fb639ef5d99ee0cf25f35db88f96a584a519ed823d89d6b537e9da1efff66fee",["Text"]="-----------------------------------\n-- Ability: Warcry\n-- Job: Warrior\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.warrior.useWarcry(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/warding_circle.lua"]={["Path"]="scripts/actions/abilities/warding_circle.lua",["SHA256"]="0186fa98600fee9ee355368a6c24d15db098535a8cc7bd189d008e3a38828bf9",["Text"]="-----------------------------------\n-- Ability: Warding Circle\n-- Grants resistance, defense, and attack against Demons to party members within the area of effect.\n-- Obtained: Samurai Level 5\n-- Recast Time: 5:00 minutes\n-- Duration: 3:00 minutes\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.samurai.use