r, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/wild_flourish.lua"]={["Path"]="scripts/actions/abilities/wild_flourish.lua",["SHA256"]="4a76e9eab31b53856483aee4aaba0c01ec717fdb4a53e17a89ab2a4281130412",["Text"]="-----------------------------------\n-- Ability: Wild Flourish\n-- Readies target for a skillchain. Requires at least two Finishing Moves.\n-- Obtained: Dancer Level 60\n-- Finishing Moves Used: 2\n-- Recast Time: 0:30\n-- Duration: 0:05\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.dancer.checkFlourishAbility(player, target, ability, true, 2)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.dancer.useWildFlourishAbility(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/wind_maneuver.lua"]={["Path"]="scripts/actions/abilities/wind_maneuver.lua",["SHA256"]="3e883e08e1353ae47b70b6ab71648cea73713b19e906eea09c959d9b4945bdc6",["Text"]="-----------------------------------\n-- Ability: Wind Maneuver\n-- Enhances the effect of wind attachments. Must have animator equipped.\n-- Obtained: Puppetmaster level 1\n-- Recast Time: 10 seconds (shared with all maneuvers)\n-- Duration: 1 minute\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.automaton.onManeuverCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.automaton.onUseManeuver(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/wind_shot.lua"]={["Path"]="scripts/actions/abilities/wind_shot.lua",["SHA256"]="2642a79b6438ae67d6b232166eb68ae75cff1891985b1f89e5eab67a498cf6e0",["Text"]="-----------------------------------\n-- Ability: Wind Shot\n-- Consumes a Wind Card to enhance wind-based debuffs. Deals wind-based magic damage\n-- Choke Effect: Enhanced DoT and VIT-\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.checkQuickDraw(player, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.corsair.useElementalShot(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/wizards_roll.lua"]={["Path"]="scripts/actions/abilities/wizards_roll.lua",["SHA256"]="154170a1f40566afab03837fffed159f27709b88103ab79143dd064ad2fb6eb6",["Text"]="-----------------------------------\n-- Ability: Wizard's Roll\n-- Enhances magic attack for party members within area of effect\n-- Optimal Job: Black Mage\n-- Lucky Number: 5\n-- Unlucky Number: 9\n-- Level 58\n-- Phantom Roll +1 Value: 2\n--\n-- Die Roll    |No BLM  |With BLM\n-- --------    -------- -----------\n-- 1           |+4      |+14\n-- 2           |+6      |+16\n-- 3           |+8      |+18\n-- 4           |+10     |+20\n-- 5           |+25     |+35\n-- 6           |+12     |+22\n-- 7           |+14     |+24\n-- 8           |+17     |+27\n-- 9           |+2      |+12\n-- 10          |+20     |+10\n-- 11          |+30     |+40\n-- Bust        |-10     |-10\n--\n-- If the Corsair is a lower level than the player receiving Wizard's Roll, the +MAB will be reduced\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/yaegasumi.lua"]={["Path"]="scripts/actions/abilities/yaegasumi.lua",["SHA256"]="b3d9f46196a8094d63d3edc730abd1cd7496acd5c0cd5e2a7976f9d7ffcea919",["Text"]="-----------------------------------\n-- Ability: Yaegasumi\n-- Description: Allows you to evade special attacks. Grants a weapon skill damage bonus that varies with the number of special attacks evaded.\n-- Obtained: SAM Level 96\n-- Recast Time: 01:00:00\n-- Duration: 00:00:45\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.samurai.checkYaegasumi(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.samurai.useYaegasumi(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/yonin.lua"]={["Path"]="scripts/actions/abilities/yonin.lua",["SHA256"]="497b3cb1514f89f74d32780d9ab488e18729d6f0a8cefb2af03c2eb4147a5bf1",["Text"]="-----------------------------------\n-- Ability: Yonin\n-- Increases enmity and enhances \"Ninja Tool Expertise\" effect, but impairs accuracy. Improves evasion and reduces enemy Critical Hit Rate when in front of target.\n-- Obtained: Ninja Level 40\n-- Recast Time: 3:00\n-- Duration: 5:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.ninja.checkYonin(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.ninja.useYonin(player, target, ability, action)\nend\n\nreturn abilityObject\n"}};
